prompt --application/shared_components/plugins/dynamic_action/ir_apex360_persian_font_switcher
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(46204136325070089)
,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'IR.APEX360.PERSIAN_FONT_SWITCHER'
,p_display_name=>'APEX360_PERSIAN_FONT_SWITCHER'
,p_category=>'STYLE'
,p_about_url=>'https://apex360.ir'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function render_persian_font_switcher (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin',
')',
'return apex_plugin.t_dynamic_action_render_result',
'is',
'    v_result      apex_plugin.t_dynamic_action_render_result;',
'    v_font_name   varchar2(100);',
'    v_selectors   varchar2(4000);',
'    v_css_file    varchar2(100);',
'begin',
'',
'    -- Read plugin attributes',
'    v_font_name := nvl(',
'        trim(p_dynamic_action.attribute_01),',
'        ''vazir''',
'    );',
'',
'    v_selectors := nvl(',
'        trim(p_dynamic_action.attribute_02),',
'        ''html, body, h1, h2, h3, h4, h5, h6, button, input, select, textarea''',
'    );',
'',
'    -- Determine CSS file',
'    v_css_file := case lower(v_font_name)',
'        when ''droidkufi''         then ''droidkufi''',
'        when ''palatino''          then ''palatino''',
'        when ''vazir''             then ''vazir''',
'        when ''samim''             then ''samim''',
'        when ''shabnam''           then ''shabnam''',
'        when ''sahel''             then ''sahel''',
'        when ''nahid''             then ''nahid''',
'        when ''tanha''             then ''tanha''',
'        else ''vazir''',
'    end;',
'',
'    -- Debug',
'    if apex_application.g_debug then',
'',
'        apex_plugin_util.debug_dynamic_action(',
'            p_plugin         => p_plugin,',
'            p_dynamic_action => p_dynamic_action',
'        );',
'',
'        apex_debug.message(''Font Name: '' || v_font_name);',
'        apex_debug.message(''CSS File: '' || v_css_file);',
'        apex_debug.message(''Selectors: '' || v_selectors);',
'',
'    end if;',
'',
'    -- Load CSS file',
'    apex_css.add_file(',
'        p_name      => v_css_file,',
'        p_directory => p_plugin.file_prefix',
'    );',
'',
'    -- Apply selected font',
'    apex_css.add(',
'        p_css => v_selectors || '' { font-family: "'' ||',
'                 apex_escape.html_attribute(v_font_name) ||',
'                 ''", Tahoma, Arial, sans-serif !important; }'',',
'        p_key => ''persian_font_apply_'' ||',
'                 lower(replace(v_font_name, '' '', ''_''))',
'    );',
'',
'    -- JavaScript callback',
'    v_result.javascript_function := ''function () { return true; }'';',
'',
'    return v_result;',
'',
'end render_persian_font_switcher;',
''))
,p_api_version=>1
,p_render_function=>'render_persian_font_switcher'
,p_substitute_attributes=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'**Persian Font Switcher for Oracle APEX**',
'Design & Development: Mojtaba Haji Aligholi Givi',
'This plugin has been designed and developed to provide flexible Persian font management and switching capabilities in Oracle APEX applications. It allows developers to easily customize and switch application fonts to enhance the user interface and im'
||'prove the Persian user experience.',
'Custom Plugin Design & Development Orders:  ',
unistr('\D83C\DF10 https://apex360.ir  '),
unistr('\2709\FE0F info@apex360.ir'),
'Contact the Developer:  ',
'LinkedIn: https://www.linkedin.com/in/mojtaba-aligholi  ',
'GitHub: https://github.com/mojtabagivi  ',
'Email: mojtaba.givi@gmail.com  ',
'Phone: 09123241271',
unistr('Copyright \00A9 2026 Mojtaba Haji Aligholi Givi. All rights reserved.'),
'All intellectual and material rights of this plugin belong to its designer and developer. Any redistribution, reproduction, or use outside the terms of the license requires permission from the copyright owner.'))
,p_version_identifier=>'1.0'
,p_files_version=>2461365134549
);
